    "requirement": "▣ 수입검사 실시기준 수립 및 준수상태\n    - 검사협정서/기준서 체결상태(사급품은 1차 협력사가 체결한 검사협정서 사본 접수 및 동일 시료/주기로 검사 실시 필요)                     \n        → 검사협정 체결이 어려울 시 검사기준서 수립으로 대체 (예: 대기업 공급 원재료,도금업종 등)\n    - 외주품 입고 시 외주사 출하성적서 접수 및 수입검사 실측값 비교검증 여부\n    - 원재료 M/SHEET 접수 시 물성 및 화학조성비 합/부 판단기준 명확화 수립\n    - 입고 LOT와 출하검사 성적서내 LOT 일치성 확보여부(원소재의 경우 M/SHEET내 검사시료 LOT 일치성)\n    - 검사협정서/기준서에 준한 일상검사/정기검사 실시상태\n    - FMB 입고 검사 : 경도, 가류도(레오메타), 비중, 분산도\n    - CMB 입고 검사 : 무늬점도\n    - 원재료(완제품) 정기검사 (최소 1회/6개월 실시) : 신율, 영구압출줄음율, 인장강도 \n    - 용기/포장 적정성 (필요시 제전 비닐/박스, 이물질 유입 방지, 제품간 간섭 방지, 물류 이동시 제품 훼손 방지,사양 식별, \n      오조립 방지, 이물질 유입방지, 체결부 좌면상태, 취급 용이성) 및 습동부/매칭부 단품 치수검사 상태\n    - 다 CAVITY 제품의 경우 CAVITY별 검사 기준 수립 및 준수 상태\n      ※ 점검기준은 CAVITY 총 수량 고려 합리적인 점검주기 설정(일상/정기) 및 이행필요\n          예) 일상 : 10 캐비티↓ : 전캐비티 검사,  11 캐비티↑ : 홀수일 Lot 홀수 캐비티/짝수일 Lot 짝수 캐비티 검사\n               정기 : 전 캐비티 검사",
    "problem": "●  수입검사 실시기준 및 준수 상태 미흡\n 1. FMB 검사협정 기준 대비 실제 수입검사 상이함\n  - 외관/점도/스코치/가류도에 대한 수입검사 진행 필요하나, 재질성적서만 접수 진행중\n * 시험실내 무늬점도계 보유중이나 실제 미운영중(레오메타 측정장비 미보유)\n 2. FMB / 컴파운드 검사협정 체결상태 미흡\n - FMB의 경우 검사협정 체결되어 있으나, 검사주기 및 검사항목 재개정 필요\n └ 공급자 / 수요자 구분 및 오륙내 시험 기준 적용하여 업데이트 필요\n - 컴파운드 검사협정 미체결",
    "actionPlan": "1) 작업자 자주검사 체크시트 개정 (검사항목 도식화)\n2) 품질 순회검사 주기(2시간/1회) 및 치수/외관 체크포인트 강화\n3) 부적합 발생 시 즉시 라인스톱 및 LOT 분리 보관 규정화",
