    "requirement": "▣ 검사용 마스터(한도견본) 관리기준 수립 및 준수상태\n    - 외주품/완성품 외관 합/부 판별용 한도견본 운영\n    - 설비 유효성 확보용 한도견본 또는 셋팅 마스터지그 제작관리 (시업시 마스터 이용한 설비 유효성 검증 실시)\n    - 검사기 신뢰도 확인을 위한 OK/NG 마스터 설정기준 및 관리상태\n    - 한도견본의 변색, 변형, 녹 발생 등으로 실제 견본품 운영이 어려울 경우 외관검사기준서로 대체 가능\n    - 목시검사(확대경) 한도견본 비치, 관리 및 이력관리",
