    "subItem": "2-5-1 검교정 프로세스/매뉴얼 (설비,계측기)",
    "requirement": "▣ 계측기/검사구 보유 및 신뢰성 확보상태 (검교정 주기설정, 교정상태)\n    - 검사협정 체결기준 시험항목 자체시험 가능한 계측장비 보유상태 (정기 신뢰성 항목별 계측기 지정 및 준수필요)\n      ※ 고가 계측기 등 자체검증 불가능 시험 항목의 경우 1차 협력사 또는 공인기관시험 인정\n          (예 : 3차원 측정기, 성분분석기 등)되나 시험결과 접수 및 이상발생 여부 검토 필요\n    - 계측기 검교정 계획 대비 실적관리 상태 (계측기 검교정 성적서/테그 관리)\n      ※ 검교정 자격인증 인원 보유 협력사는 자체 검증 근거 확보시 인정\n      ※ 검교정 실시 후 불확도 고려 합/부 판정 실시 (판정 기준 수립)\n         → 신뢰수준 95%기준으로 측정된 불확도 대비 측정대상 관리 공차가 4배 이상시 사용 가능\n             예) 신뢰수준 95% 기준 불확도 0.002mm인 계측장비는 관리공차 ±0.008mm 이상이 부품만 측정가능 (1:4 비율 반영)\n    - 주요 검사구 유효성 확보여부 점검결과(검사구 사용시 마모,유격 발생에 따른 측정 유효성 확인 필요)\n         예) 사출품 측정용 검사구 3차원 데이터 측정결과, 치수 보증된 제품을 통한 자체 비교검증 데이터 등",
