    "actionPlan": "1) 전 설비 설비보유 LIST 및 A/B/C 등급분류 평가 실시\n2) 연간 설비정기점검 계획서 수립 및 점검 체크시트 제정\n3) 칠러 및 냉각수 온도센서 교정 일치화 및 보전이력카드 기록 누적",
