    "requirement": "▣ 원자재 및 재공품, 출하품 LOT 추적성 관리 프로세스 수립 및 준수상태\n [CASE1] LOT수작업관리 - 파렛트or 부품단위 \n   ▷ 보안/안전 부품 별도 식별 표시 : LOT타각, 식별마크 등\n   ▷ 선입/선출 관리기준 유무 (공정~출하) - 관리 대장, 레이아웃\n   ▷ 선입 선출 준수 여부 - 중요 부품 샘플링 점검, 인라인 투입 제품, 투입 대기 제품, 자재창고 적재 제품 생산일 점검 \n   ▷ 부품 LOT 표기 여부  (표준류 지정시) - 각인, 스티커, 타각 등\n   ▷ 부품 LOT기록 마스터리스트 관리되고 역추적 가능 여부\n [CASE2] LOT전산관리 - 파렛트단위 \n   ▷ 파렛트 납품단위 이종 LOT 생산품 혼입 방지 프로세스 수립 - 파렛트 납입 제품 혼입여부 실물 확인\n   ▷ 파렛트 바코드 라벨 부착 관리 여부 (바코드 라벨 유실 방지 대책 포함) \n    - 생산 LOT 정보 포함, 보안/안전 부품 별도 식별 표시\n   ▷ 파렛트 단위 공정 투입시 바코드 리딩     - 미리딩 오류 발생 알람 및 선입선출 인터락 유무\n   ▷ 파렛트 단위 LOT 전산 관리되고, 역추적 가능 여부\n[CASE3] LOT전산관리 - 부품단위 \n   ▷ 부품 바코드 라벨 부착 관리 여부 (바코드 라벨 유실 방지 대책 포함) \n    - 생산 LOT 정보 포함, 보안/안전 부품 별도 식별 표시\n    - 라벨 부착 위치는 정해져 있으며, 불완전 부착에 의한 상대물 간섭 없을것\n   ▷ 부품단위 공정 투입시 바코드 리딩 - 미리딩 오류 발생 알람 및 선입선출 인터락 유무\n   ▷ 부품 단위 LOT 전산 관리되고, 역추적 가능 여부",
    "problem": "● 부자재 LOT 추적성 관리 미흡\n - PAD / Clip 등 해포 후 공정내에서 사용되는 부자재에 대한 LOT 식별 관리 안됨\n  └ 해포 후 BOX 보관중인 부자재 LOT 식별 안됨",
    "actionPlan": "1) 원부자재 입고부터 투입, 공정, 출하까지 LOT 추적 매뉴얼 개정\n2) FMB 및 원자재 보관 렉 선입선출 구조(경사 슬라이딩렉 또는 라인별 순번대차) 정비\n3) 잔량 FMB 밀봉 보관 및 잔량 LOT 식별표 부착 표준화",
