    "requirement": "▣ 안전사고 발생 예방을 위한 업무 프로세스 수립 및 준수실태\n    - 작업자 안전관리 프로세스 수립 및 준수실태(현장확인)\n      : 생산중 핸드폰 미사용을 위한 별도 보관대 설치 및 시건장치, 라인투입전 휴대폰 미반납후 사용시 조치방안\n       : 안전 보호장구(보안경/헬멧/장갑 등) 착용 기준수립 및 이행상태 점검(일상)\n    - 업종별 안전사고 발생 예방을 위한 설비/레이아웃 반영\n          ⇒ 예) 프레스 : 작업자 감지센서(안전BAR), 양수 조작버튼, 플라이휠 커버 등\n                    도금 : 마스크 착용, 위험물(약품) 별도 보관장 마련 및 취급기준 수립\n                    용접 : 안전장갑 및 보호 안경 착용, 용접 스페터 비산 방지용 보호막 설치 등 \n                    로봇, 자동 기계 설비(LOTO) : 전원차단(Lock-Out)과 경고표지 부착(Tag-Out) 실시\n    - 작업 현장내 안전표지/수칙 게시 및 작업자 교육\n    - 작업 현장내 위험요소(위험물)에 대한 사고예방 장비/시설물 설치 및 식별 표준류 반영\n      1) 표준류 게시된 현위치 기준 소화 방재시설 위치 및 비상대피 동선 표기된 표준류 작성/게시\n      2) 설비 간섭 등 고려 소화 방재시설 식별표, 비상대비 표시등 2층높이 반영\n    - 운영중인 설비에 대한 정기 안전관리 프로세스 수립 및 이행상태\n    - 설비 점검시(계획/비계획) 업무 처리절차 수립 : 2인 1개조 운영, 비정상 가동 예방절차 등",
