    "requirement": "▣ 『정성품질』 운영 프로세스는 마련되어 있고, 점검 및 포상활동은 실시되는가?\n   ▷『정성품질』 활동 관련 업무분장(키맨)\n     - 『정성품질』 수평전개 교육 담당/ 품질문제 발생시 개선활동 담당/ 고객사 협업 담당 등\n  ▷ 정성품질 통신문 품질현황판 게시 및 사내 임직원 전파교육 실시 이력 관리\n  ▷제조현장 『정성품질』관련 예방/개선 프로세스 수립(제조현장 반영내역 확인)\n     - 예방활동 : 휴먼에러 발생 예방을 위한 작업자/공정/설비 등 예방점검 개선 이력\n     - 개선활동 : 중요 품질문제(작업자 휴먼에러) 발생시 해당 공정 시정조치 활동 이력 \n                      → 발생 원인에 대한 세부적인 원인 분류 및 근본적인 시정조치 활동 실시\n  ▷『정성품질』 유지 및 관리실태 점검 활동 실시이력(현황 및 개선대책 경영진 보고)\n     - 제조현장 표준류 준수, 작업공수 일치성, 공정검사 기준 준수 등 『정성품질』 관리실태 정기적 점검이력\n      ex) 제조현장 확인시 수작업 조립 어려움, 작업 공수 불명확, 역조립/오조립 가능성, 신규/임시 작업자 표준 준수 등 \n            『정성품질』 개선 필요항목 확인 \n  ▷『정성품질』 정착화 및 붐업 조성을 위한 포상제도 운영관리\n     - 『정성품질』관련 사전 예방활동 및 개선 우수사례에 대한 포상제도 운영기준 수립 및 실적",
